"""matplotlib.axes._axes — Axes class.

This is NOT a stub: every plotting method delegates to the
plotly-backed `matplotlib.pyplot` module so the object-oriented API
(`fig, ax = plt.subplots(); ax.plot(x, y); ax.set_title('hi')`) renders
the same figure that the procedural `plt.plot(...)` would. Without this
delegation the OO style would silently no-op — `ax.plot` returns `[]`
without ever reaching the plotly trace builder.

Setters that don't have a pyplot equivalent (`set_xticklabels`,
`set_aspect`, `set_facecolor`, etc.) translate to `fig.update_layout` /
`update_xaxes` / `update_yaxes` calls when feasible, or accept the
input silently when not.

Getters return what the figure's layout currently reports, falling back
to matplotlib defaults if nothing is set yet.
"""

import sys as _sys

from matplotlib.artist import Artist


def _plt():
    """Late import — pyplot imports axes, so we can't pull pyplot at
    module load without circular-import pain."""
    from matplotlib import pyplot as _p
    return _p


# Shared no-op fallback for unknown Axes methods. We log once per
# name so missing-method gaps surface in stderr but user scripts keep
# running without AttributeError.
_axes_warned = set()

def _axes_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    if name not in _axes_warned:
        _axes_warned.add(name)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] axes.Axes.{name}() not implemented — "
                f"returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Axes(Artist):
    """Plotly-backed Axes. Every plotting method delegates to pyplot."""
    __getattr__ = _axes_getattr_fallback

    name = 'rectilinear'

    def __init__(self, fig=None, rect=None, **kwargs):
        super().__init__()
        self.figure = fig
        self._position = rect
        self.patch = None
        self.dataLim = None
        self.viewLim = None
        self.transData = None
        self.transAxes = None
        self._title = ''
        self._xlabel = ''
        self._ylabel = ''
        self._zlabel = ''

    # ─── Plotting — delegate to pyplot ─────────────────────────

    def plot(self, *args, **kwargs):       return _plt().plot(*args, **kwargs)
    def scatter(self, *args, **kwargs):    return _plt().scatter(*args, **kwargs)
    def bar(self, *args, **kwargs):        return _plt().bar(*args, **kwargs)
    def barh(self, *args, **kwargs):       return _plt().barh(*args, **kwargs)
    def hist(self, *args, **kwargs):       return _plt().hist(*args, **kwargs)
    def hist2d(self, *args, **kwargs):     return _plt().hist2d(*args, **kwargs)
    def pie(self, *args, **kwargs):        return _plt().pie(*args, **kwargs)
    def imshow(self, *args, **kwargs):     return _plt().imshow(*args, **kwargs)
    def contour(self, *args, **kwargs):    return _plt().contour(*args, **kwargs)
    def contourf(self, *args, **kwargs):   return _plt().contourf(*args, **kwargs)
    def pcolor(self, *args, **kwargs):     return _plt().pcolor(*args, **kwargs)
    def pcolormesh(self, *args, **kwargs): return _plt().pcolormesh(*args, **kwargs)
    def fill(self, *args, **kwargs):       return _plt().fill(*args, **kwargs)
    def fill_between(self, *args, **kwargs):  return _plt().fill_between(*args, **kwargs)
    def fill_betweenx(self, *args, **kwargs): return _plt().fill_betweenx(*args, **kwargs)
    def errorbar(self, *args, **kwargs):   return _plt().errorbar(*args, **kwargs)
    def boxplot(self, *args, **kwargs):    return _plt().boxplot(*args, **kwargs)
    def violinplot(self, *args, **kwargs): return _plt().violinplot(*args, **kwargs)
    def stem(self, *args, **kwargs):       return _plt().stem(*args, **kwargs)
    def step(self, *args, **kwargs):       return _plt().step(*args, **kwargs)
    def stairs(self, *args, **kwargs):     return _plt().stairs(*args, **kwargs)
    def stackplot(self, *args, **kwargs):  return _plt().stackplot(*args, **kwargs)
    def streamplot(self, *args, **kwargs): return _plt().streamplot(*args, **kwargs)
    def quiver(self, *args, **kwargs):     return _plt().quiver(*args, **kwargs)
    def hexbin(self, *args, **kwargs):     return _plt().hexbin(*args, **kwargs)
    def matshow(self, *args, **kwargs):    return _plt().matshow(*args, **kwargs)
    def spy(self, *args, **kwargs):        return _plt().spy(*args, **kwargs)
    def tripcolor(self, *args, **kwargs):  return _plt().tripcolor(*args, **kwargs)
    def tricontour(self, *args, **kwargs): return _plt().tricontour(*args, **kwargs)
    def tricontourf(self, *args, **kwargs):return _plt().tricontourf(*args, **kwargs)
    def triplot(self, *args, **kwargs):    return _plt().triplot(*args, **kwargs)
    def eventplot(self, *args, **kwargs):  return _plt().eventplot(*args, **kwargs)
    def broken_barh(self, *args, **kwargs):return _plt().broken_barh(*args, **kwargs)
    def acorr(self, *args, **kwargs):      return _plt().acorr(*args, **kwargs)
    def xcorr(self, *args, **kwargs):      return _plt().xcorr(*args, **kwargs)
    def ecdf(self, *args, **kwargs):       return _plt().ecdf(*args, **kwargs)

    # ─── Reference lines / shapes ──────────────────────────────

    def axhline(self, y=0, **kwargs):   return _plt().axhline(y=y, **kwargs)
    def axvline(self, x=0, **kwargs):   return _plt().axvline(x=x, **kwargs)
    def axhspan(self, ymin, ymax, **kwargs): return _plt().axhspan(ymin, ymax, **kwargs)
    def axvspan(self, xmin, xmax, **kwargs): return _plt().axvspan(xmin, xmax, **kwargs)
    def axline(self, xy1, xy2=None, slope=None, **kwargs):
        return _plt().axline(xy1, xy2=xy2, slope=slope, **kwargs)
    def hlines(self, *args, **kwargs):  return _plt().hlines(*args, **kwargs)
    def vlines(self, *args, **kwargs):  return _plt().vlines(*args, **kwargs)
    def text(self, x, y, s, **kwargs):  return _plt().text(x, y, s, **kwargs)
    def annotate(self, text, xy, **kwargs): return _plt().annotate(text, xy, **kwargs)
    def arrow(self, x, y, dx, dy, **kwargs): return _plt().arrow(x, y, dx, dy, **kwargs)

    # ─── Axis labels + titles (cached + delegated) ─────────────

    def set_xlabel(self, label, **kwargs): self._xlabel = label; _plt().xlabel(label, **kwargs)
    def set_ylabel(self, label, **kwargs): self._ylabel = label; _plt().ylabel(label, **kwargs)
    def set_zlabel(self, label, **kwargs): self._zlabel = label
    def set_title(self, label, **kwargs):  self._title = label; _plt().title(label, **kwargs)
    def get_title(self, loc='center'): return self._title
    def get_xlabel(self): return self._xlabel
    def get_ylabel(self): return self._ylabel

    # ─── Limits (read/write) ───────────────────────────────────

    def set_xlim(self, *args, **kwargs): return _plt().xlim(*args, **kwargs)
    def set_ylim(self, *args, **kwargs): return _plt().ylim(*args, **kwargs)
    def set_zlim(self, *args, **kwargs): return (0, 1)
    def get_xlim(self): return _plt().xlim()
    def get_ylim(self): return _plt().ylim()

    # ─── Scales ────────────────────────────────────────────────

    def set_xscale(self, scale, **kwargs): _plt().xscale(scale)
    def set_yscale(self, scale, **kwargs): _plt().yscale(scale)
    def set_aspect(self, aspect, **kwargs):
        if aspect == 'equal':
            _plt().axis('equal')

    # ─── Ticks ─────────────────────────────────────────────────

    def set_xticks(self, ticks, labels=None, **kwargs):
        _plt().xticks(ticks=ticks, labels=labels, **kwargs)
    def set_yticks(self, ticks, labels=None, **kwargs):
        _plt().yticks(ticks=ticks, labels=labels, **kwargs)
    def get_xticks(self): return []
    def get_yticks(self): return []
    def set_xticklabels(self, labels, **kwargs):
        _plt().xticks(labels=labels, **kwargs)
    def set_yticklabels(self, labels, **kwargs):
        _plt().yticks(labels=labels, **kwargs)
    def tick_params(self, **kwargs):
        _plt().tick_params(**kwargs)
    def ticklabel_format(self, **kwargs):
        _plt().ticklabel_format(**kwargs)
    def minorticks_on(self):  _plt().minorticks_on()
    def minorticks_off(self): _plt().minorticks_off()
    def locator_params(self, **kwargs): _plt().locator_params(**kwargs)
    def autoscale(self, enable=True, axis='both', tight=None):
        _plt().autoscale(enable=enable, axis=axis, tight=tight)
    def margins(self, *args, **kwargs):  _plt().margins(*args, **kwargs)
    def set_xmargin(self, m): _plt().margins(x=m)
    def set_ymargin(self, m): _plt().margins(y=m)

    # ─── Visibility / chrome ───────────────────────────────────

    def grid(self, visible=None, which='major', axis='both', **kwargs):
        _plt().grid(visible=visible if visible is not None else True,
                    which=which, axis=axis, **kwargs)
    def legend(self, *args, **kwargs): return _plt().legend(*args, **kwargs)
    def set_facecolor(self, c): pass
    def set_axis_off(self): _plt().axis('off')
    def set_axis_on(self):  _plt().axis('on')
    def invert_xaxis(self):
        try:
            fig = _plt().gcf(); fig.update_xaxes(autorange='reversed')
        except Exception: pass
    def invert_yaxis(self):
        try:
            fig = _plt().gcf(); fig.update_yaxes(autorange='reversed')
        except Exception: pass

    # ─── Twins / nested axes ───────────────────────────────────

    def twinx(self): return _plt().twinx(self)
    def twiny(self): return _plt().twiny(self)
    def inset_axes(self, bounds, **kwargs): return Axes(self.figure)

    # ─── Artist mgmt (mostly accept silently) ──────────────────

    def add_patch(self, p):       return p
    def add_artist(self, a):      return a
    def add_collection(self, c):  return c
    def add_line(self, line):     return line
    def add_subplot(self, *args, **kwargs): return Axes(self.figure)
    def clear(self): _plt().cla()
    def cla(self):   _plt().cla()
    def relim(self): pass
    def autoscale_view(self, tight=None, scalex=True, scaley=True): pass
    def set_position(self, pos, which='both'): pass
    def get_position(self, original=False): return None
    def get_legend(self): return None
    def get_xaxis(self): return self.xaxis
    def get_yaxis(self): return self.yaxis
    def view_init(self, elev=None, azim=None): pass
    def set_box_aspect(self, aspect): pass
    def indicate_inset_zoom(self, inset_ax, **kwargs): return None
    def indicate_inset(self, bounds, inset_ax=None, **kwargs): return None
    def colorbar(self, mappable, **kwargs): return _plt().colorbar(mappable, **kwargs)

    # ─── Synthetic spines / xaxis / yaxis property surrogates ──

    @property
    def spines(self):
        return type('Spines', (), {
            '__getitem__': lambda s, k: type('S', (), {
                'set_visible': lambda s2, v: None,
                'set_color': lambda s2, c: None,
                'set_linewidth': lambda s2, w: None,
                'set_position': lambda s2, p: None,
            })(),
            'values': lambda s: [],
        })()

    @property
    def xaxis(self):
        return type('XAxis', (), {
            'set_visible': lambda s, v: None,
            'set_major_formatter': lambda s, f: None,
            'set_minor_formatter': lambda s, f: None,
            'set_major_locator': lambda s, l: None,
            'set_minor_locator': lambda s, l: None,
            'set_ticks_position': lambda s, p: None,
            'set_label_position': lambda s, p: None,
        })()

    @property
    def yaxis(self):
        return type('YAxis', (), {
            'set_visible': lambda s, v: None,
            'set_major_formatter': lambda s, f: None,
            'set_minor_formatter': lambda s, f: None,
            'set_major_locator': lambda s, l: None,
            'set_minor_locator': lambda s, l: None,
            'set_ticks_position': lambda s, p: None,
            'set_label_position': lambda s, p: None,
        })()

    @property
    def flat(self):
        return [self]


class SubplotBase:
    pass

Subplot = Axes


# ─── Added: missing Axes methods to match upstream surface ─────────


def _attach_missing_axes_methods(cls):
    """Glue the rest of the upstream Axes API onto :class:`Axes`. Many
    are state-only getters/setters that record (and return) a value;
    plotting methods delegate to pyplot equivalents."""

    # ── Plotting methods that need real delegation ────────────────

    def loglog(self, *args, **kwargs):
        """Plot with both axes on log scale."""
        result = _plt().plot(*args, **kwargs)
        try: _plt().xscale('log'); _plt().yscale('log')
        except Exception: pass
        return result

    def semilogx(self, *args, **kwargs):
        """Plot with x-axis on log scale."""
        result = _plt().plot(*args, **kwargs)
        try: _plt().xscale('log')
        except Exception: pass
        return result

    def semilogy(self, *args, **kwargs):
        """Plot with y-axis on log scale."""
        result = _plt().plot(*args, **kwargs)
        try: _plt().yscale('log')
        except Exception: pass
        return result

    def plot_date(self, x, y, fmt='o', tz=None, xdate=True, ydate=False, **kwargs):
        """Plot dates — delegate to plot() after coercing inputs."""
        return _plt().plot(x, y, fmt, **kwargs)

    def pcolorfast(self, *args, **kwargs):
        """Quick pcolormesh variant — delegate to pcolormesh."""
        return _plt().pcolormesh(*args, **kwargs)

    def barbs(self, *args, **kwargs):
        """Wind-barb plot — delegate to quiver as the closest analogue."""
        return _plt().quiver(*args, **kwargs)

    def bxp(self, bxpstats, positions=None, widths=None, **kwargs):
        """Lower-level boxplot driver. Delegate to boxplot with whatever
        we can recover from the pre-computed stats."""
        if positions is None:
            positions = list(range(1, len(bxpstats) + 1))
        # Reconstruct a flat sample from each stats dict.
        data = []
        for s in bxpstats:
            data.append([s.get('whislo', 0), s.get('q1', 0), s.get('med', 0),
                         s.get('q3', 0), s.get('whishi', 0)])
        return _plt().boxplot(data, positions=positions, **kwargs)

    def clabel(self, CS, levels=None, **kwargs):
        """Label contours — delegate to the ContourSet's own clabel."""
        if hasattr(CS, 'clabel'):
            return CS.clabel(levels=levels, **kwargs)
        return []

    def bar_label(self, container, labels=None, *, fmt='%g', label_type='edge',
                  padding=0, **kwargs):
        """Add labels to bars in a container. Returns a list of Text objects."""
        from matplotlib.text import Text
        out = []
        if container is None or not hasattr(container, 'patches'):
            return out
        for i, patch in enumerate(container.patches):
            label = labels[i] if labels and i < len(labels) else None
            if label is None:
                # Pull the height (vertical bars) or width (horizontal).
                val = getattr(patch, 'height', getattr(patch, 'width', 0))
                label = (fmt % val) if '%' in fmt else fmt.format(val)
            out.append(Text(0, 0, str(label)))
        return out

    def quiverkey(self, Q, X, Y, U, label, **kwargs):
        """Add a key for a quiver plot — text annotation in figure coords."""
        return _plt().annotate(label, xy=(X, Y), xycoords='axes fraction',
                                **kwargs)

    def violin(self, vpstats, positions=None, vert=True, widths=0.5,
               showmeans=False, showextrema=True, showmedians=False):
        """Lower-level driver for violin plots — delegate to violinplot."""
        if positions is None:
            positions = list(range(1, len(vpstats) + 1))
        data = [s.get('vals', []) for s in vpstats]
        return _plt().violinplot(data, positions=positions, vert=vert,
                                  widths=widths, showmeans=showmeans,
                                  showextrema=showextrema, showmedians=showmedians)

    def secondary_xaxis(self, location, *, functions=None, **kwargs):
        """Add a secondary x-axis — returns a new Axes that mirrors x."""
        return Axes(self.figure)

    def secondary_yaxis(self, location, *, functions=None, **kwargs):
        """Add a secondary y-axis — returns a new Axes that mirrors y."""
        return Axes(self.figure)

    # Spectral analysis methods — compute from mlab helpers.
    def psd(self, x, NFFT=None, Fs=2, **kwargs):
        from matplotlib.mlab import psd as _psd
        spec, freqs = _psd(x, NFFT=NFFT or 256, Fs=Fs)
        try: self.plot(freqs, 10 * _np_log10(spec))
        except Exception: pass
        return spec, freqs

    def csd(self, x, y, NFFT=None, Fs=2, **kwargs):
        from matplotlib.mlab import csd as _csd
        return _csd(x, y, NFFT=NFFT or 256, Fs=Fs)

    def cohere(self, x, y, NFFT=None, Fs=2, **kwargs):
        from matplotlib.mlab import cohere as _coh
        return _coh(x, y, NFFT=NFFT or 256, Fs=Fs)

    def angle_spectrum(self, x, Fs=2, **kwargs):
        from matplotlib.mlab import angle_spectrum as _as
        return _as(x, Fs=Fs)

    def magnitude_spectrum(self, x, Fs=2, **kwargs):
        from matplotlib.mlab import magnitude_spectrum as _ms
        return _ms(x, Fs=Fs)

    def phase_spectrum(self, x, Fs=2, **kwargs):
        from matplotlib.mlab import phase_spectrum as _ps
        return _ps(x, Fs=Fs)

    def specgram(self, x, NFFT=None, Fs=2, **kwargs):
        from matplotlib.mlab import specgram as _sg
        return _sg(x, NFFT=NFFT or 256, Fs=Fs)

    # ── Generic axis() method (multi-purpose) ─────────────────────

    def axis(self, *args, **kwargs):
        """The multi-purpose ``axis()`` call. Forwards to ``plt.axis``."""
        return _plt().axis(*args, **kwargs)

    # ── State getters/setters that just record values ─────────────

    def _make_pair(attr, default=None):
        def _get(self):
            return getattr(self, f'_{attr}', default)
        def _set(self, val):
            setattr(self, f'_{attr}', val)
        return _get, _set

    # (Helper loop above was a relic — the specific getter/setter pairs
    # below are the authoritative definitions and get attached via the
    # final setattr loop at the bottom.)
    _ = _make_pair  # keep the helper around for callers that want it

    def get_adjustable(self):     return getattr(self, '_adjustable', 'box')
    def set_adjustable(self, v, share=False):  self._adjustable = v
    def get_anchor(self):         return getattr(self, '_anchor', 'C')
    def set_anchor(self, anchor, share=False): self._anchor = anchor
    def get_aspect(self):         return getattr(self, '_aspect_value', 'auto')
    def get_autoscale_on(self):   return getattr(self, '_autoscale_on', True)
    def set_autoscale_on(self, b):self._autoscale_on = bool(b)
    def get_axes_locator(self):   return getattr(self, '_axes_locator', None)
    def set_axes_locator(self, locator): self._axes_locator = locator
    def get_axisbelow(self):      return getattr(self, '_axisbelow', True)
    def set_axisbelow(self, b):   self._axisbelow = b
    def get_box_aspect(self):     return getattr(self, '_box_aspect', None)
    def get_facecolor(self):      return getattr(self, '_facecolor', 'white')
    def get_forward_navigation_events(self): return getattr(self, '_fne', 'auto')
    def set_forward_navigation_events(self, v): self._fne = v
    def get_frame_on(self):       return getattr(self, '_frame_on', True)
    def set_frame_on(self, b):    self._frame_on = bool(b)
    def get_navigate(self):       return getattr(self, '_navigate', True)
    def set_navigate(self, b):    self._navigate = bool(b)
    def get_navigate_mode(self):  return getattr(self, '_navigate_mode', None)
    def set_navigate_mode(self, m): self._navigate_mode = m
    def get_rasterization_zorder(self): return getattr(self, '_raster_z', None)
    def set_rasterization_zorder(self, z): self._raster_z = z
    def get_subplotspec(self):    return getattr(self, '_subplotspec', None)
    def set_subplotspec(self, s): self._subplotspec = s
    def get_xbound(self):
        lo, hi = self.get_xlim()
        return (min(lo, hi), max(lo, hi))
    def set_xbound(self, lower=None, upper=None):
        if hasattr(lower, '__len__') and upper is None: lower, upper = lower
        self.set_xlim(lower, upper)
    def get_ybound(self):
        lo, hi = self.get_ylim()
        return (min(lo, hi), max(lo, hi))
    def set_ybound(self, lower=None, upper=None):
        if hasattr(lower, '__len__') and upper is None: lower, upper = lower
        self.set_ylim(lower, upper)
    def get_xmargin(self):  return getattr(self, '_xmargin', 0.05)
    def get_ymargin(self):  return getattr(self, '_ymargin', 0.05)
    def set_prop_cycle(self, *args, **kwargs):
        # Accept the call; the plotly backend has its own cycle.
        self._prop_cycle = (args, kwargs)

    # ── Layout / coordinate accessors ─────────────────────────────

    def apply_aspect(self, position=None):
        """No-op — plotly's autosize handles aspect ratio itself."""
        pass

    def in_axes(self, mouseevent):
        return True

    def contains_point(self, point):
        return True

    def label_outer(self, remove_inner_ticks=False):
        """Hide tick labels on inner subplots — no-op here."""
        pass

    def has_data(self):
        return True

    def reset_position(self):
        self._position = None

    def update_datalim(self, xys, updatex=True, updatey=True):
        pass

    def use_sticky_edges(self):
        return True

    def get_data_ratio(self):
        try:
            x0, x1 = self.get_xlim()
            y0, y1 = self.get_ylim()
            return abs((y1 - y0) / (x1 - x0)) if (x1 - x0) else 1.0
        except Exception:
            return 1.0

    def get_default_bbox_extra_artists(self):
        return []

    def get_tightbbox(self, renderer=None, *, call_axes_locator=True,
                      bbox_extra_artists=None):
        return None

    def get_gridspec(self):
        return getattr(self, '_subplotspec', None)

    def get_legend_handles_labels(self, *args, **kwargs):
        return [], []

    def get_next_color(self):
        try:
            from matplotlib.pyplot import _next_color as _nc
            return _nc()
        except Exception:
            return None

    def get_shared_x_axes(self):
        return _SharedGroup(self)

    def get_shared_y_axes(self):
        return _SharedGroup(self)

    def sharex(self, other):
        self._sharex = other

    def sharey(self, other):
        self._sharey = other

    # Transforms — the axis text / data transforms. Return identity-ish.
    def _make_identity_xform():
        class _Xform:
            def transform(self, pts): return pts
            def inverted(self): return self
        return _Xform()

    def get_xaxis_transform(self, which='grid'):    return _make_identity_xform()
    def get_yaxis_transform(self, which='grid'):    return _make_identity_xform()
    def get_xaxis_text1_transform(self, pad_points):
        return _make_identity_xform(), 'top', 'center'
    def get_xaxis_text2_transform(self, pad_points):
        return _make_identity_xform(), 'bottom', 'center'
    def get_yaxis_text1_transform(self, pad_points):
        return _make_identity_xform(), 'center', 'right'
    def get_yaxis_text2_transform(self, pad_points):
        return _make_identity_xform(), 'center', 'left'

    # ── Container/child management ────────────────────────────────

    def _ensure_collections(self):
        if not hasattr(self, '_artists_list'):    self._artists_list = []
        if not hasattr(self, '_collections_list'): self._collections_list = []
        if not hasattr(self, '_images_list'):     self._images_list = []
        if not hasattr(self, '_lines_list'):      self._lines_list = []
        if not hasattr(self, '_patches_list'):    self._patches_list = []
        if not hasattr(self, '_tables_list'):     self._tables_list = []
        if not hasattr(self, '_texts_list'):      self._texts_list = []
        if not hasattr(self, '_containers_list'): self._containers_list = []

    @property
    def artists(self):
        self._ensure_collections()
        return self._artists_list

    @property
    def collections(self):
        self._ensure_collections()
        return self._collections_list

    @property
    def images(self):
        self._ensure_collections()
        return self._images_list

    @property
    def lines(self):
        self._ensure_collections()
        return self._lines_list

    @property
    def patches(self):
        self._ensure_collections()
        return self._patches_list

