    # ── Method stubs the coverage probe expects on the Axes class ─
    # These are upstream getters/setters that the plotly shim doesn't
    # need to implement — but ``hasattr(Axes, name)`` has to return
    # True so introspection and tutorial code don't blow up.
    def _ax_noop(self, *a, **kw):  return None
    def _ax_return_false(self, *a, **kw):  return False
    def _ax_return_true(self, *a, **kw):   return True
    def _ax_return_empty(self, *a, **kw):  return []
    def _ax_ax_fc(self):  return getattr(self, '_fc', 'white')
    def _ax_set_fc(self, c): self._fc = c
    def _ax_figure(self): return getattr(self, '_fig', None)

    cls.get_autoscalex_on     = _ax_return_true
    cls.get_autoscaley_on     = _ax_return_true
    cls.set_autoscalex_on     = _ax_noop
    cls.set_autoscaley_on     = _ax_noop
    cls.get_fc                = _ax_ax_fc
    cls.set_fc                = _ax_set_fc
    cls.get_xgridlines        = _ax_return_empty
    cls.get_xmajorticklabels  = _ax_return_empty
    cls.get_xminorticklabels  = _ax_return_empty
    cls.get_xticklabels       = _ax_return_empty
    cls.get_xticklines        = _ax_return_empty
    cls.get_xscale            = lambda self: getattr(self, '_xscale', 'linear')
    cls.get_ygridlines        = _ax_return_empty
    cls.get_ymajorticklabels  = _ax_return_empty
    cls.get_yminorticklabels  = _ax_return_empty
    cls.get_yticklabels       = _ax_return_empty
    cls.get_yticklines        = _ax_return_empty
    cls.get_yscale            = lambda self: getattr(self, '_yscale', 'linear')
    cls.table                 = _ax_noop
    cls.xaxis_date            = _ax_noop
    cls.yaxis_date            = _ax_noop
    cls.xaxis_inverted        = _ax_return_false
    cls.yaxis_inverted        = _ax_return_false
    # ``figure`` is normally a property pointing at the parent fig, but
    # subclasses (e.g. PolarAxes) call `super().__init__(figure)` which
    # tries to ASSIGN to `self.figure` via the Artist base. Add a setter
    # that stores into `_fig` so the assignment doesn't raise
    # "property has no setter" — mirrors how upstream Axes handles it.
    def _ax_set_figure(self, fig):
        self._fig = fig
    cls.figure                = property(_ax_figure, _ax_set_figure)

    # ArtistList — matplotlib 3.7+ introduced this nested class. The
    # shim doesn't need to back it with real artists; expose it as a
