# Tiny helper used by get_shared_x_axes / get_shared_y_axes.
class _SharedGroup:
    """A trivial group containing only the source axes — mirrors the
    Grouper view upstream returns when there are no shared axes."""

    def __init__(self, ax):
        self._members = [ax]

    def get_siblings(self, ax):
        return list(self._members)

    def joined(self, a, b):
        return a is b

    def __iter__(self):
        return iter([self._members])


# Lazily imported _np.log10 — avoid pulling numpy at module load.
def _np_log10(x):
    import numpy as _np
    return _np.log10(x)


